  N[2] = (-C1)*Pf2*Ph11 + Pf2*Ph11*Z1 + C1*Pf2*Ph12*u*fabs(k) - Pf2*Ph12*u*Z1*fabs(k);
  D[0] = 4*B1*B2*C1*Ph21 - 4*pow(B1,2)*Ph21*Z1;
